        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split into core and pre-release
        if '-' in v_without_build:
            core, prerelease = v_without_build.split('-', 1)
        else:
            core = v_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            identifiers = prerelease.split('.')
        else:
            identifiers = None

        return (major, minor, patch, identifiers)

    def compare_prerelease(id1, id2):
        # Returns -1 if id1 < id2, 0 if equal, 1 if id1 > id2
        is_num1 = id1.isdigit()
        is_num2 = id2.isdigit()

        if is_num1 and is_num2:
            # Both numeric: compare numerically
            num1 = int(id1)
            num2 = int(id2)
            if num1 < num2:
                return -1
            elif num1 > num2:
                return 1
            else:
                return 0
        elif is_num1:
            # id1 is numeric, id2 is not: numeric sorts first
            return -1
        elif is_num2:
            # id2 is numeric, id1 is not: numeric sorts first
            return 1
        else:
            # Both non-numeric: compare by ASCII order
            if id1 < id2:
                return -1
            elif id1 > id2:
                return 1
            else:
                return 0

    def sort_key(v_with_index):
        v, index = v_with_index
        major, minor, patch, identifiers = parse_version(v)

        # Build a sort key tuple
        # Core version comparison (major, minor, patch)
        sort_tuple = (major, minor, patch)

        # Pre-release comparison
        if identifiers is None:
            # No pre-release: sorts after same version with pre-release
            # Use a tuple that sorts after any pre-release list
            prerelease_key = (1,)  # 1 indicates no pre-release
        else:
            # Has pre-release: sorts before same version without pre-release
            # Convert identifiers to a comparable form
            converted = []
            for id_str in identifiers:
                if id_str.isdigit():
                    # Numeric: (0, numeric_value)
                    converted.append((0, int(id_str)))
                else:
                    # Non-numeric: (1, string_value)
                    converted.append((1, id_str))
            prerelease_key = (0, tuple(converted))  # 0 indicates has pre-release

        return (sort_tuple, prerelease_key, index)

    # Add original index to maintain input order for equal precedence
    indexed_versions = [(v, i) for i, v in enumerate(versions)]

    # Sort using the key function
    sorted_versions = sorted(indexed_versions, key=sort_key)

    # Return just the version strings
    return [v for v, _ in sorted_versions]

